insert into public.quiz_questions (id,category,question,options,correct_option,explanation,image_url) values
(1,'PIC Júnior','Qual é uma característica central de um projeto de iniciação científica?','{"A": "Investigar uma pergunta usando métodos organizados", "B": "Copiar informações sem analisar", "C": "Apresentar apenas opiniões pessoais", "D": "Evitar registrar os resultados"}'::jsonb,'A','A iniciação científica envolve investigação, planejamento, coleta e análise de informações.', null),
(2,'PIC Júnior','Para que serve uma pergunta de pesquisa?','{"A": "Para decorar a apresentação", "B": "Para orientar o que será investigado", "C": "Para substituir os resultados", "D": "Para garantir que a hipótese esteja correta"}'::jsonb,'B','A pergunta delimita o problema e orienta as etapas da investigação.', null),
(3,'PIC Júnior','O que é uma hipótese em uma pesquisa?','{"A": "Uma resposta provisória que será investigada", "B": "Uma conclusão que não pode mudar", "C": "Uma lista de materiais", "D": "Uma opinião sem relação com o tema"}'::jsonb,'A','A hipótese é uma explicação provisória que precisa ser confrontada com evidências.', null),
(4,'PIC Júnior','Qual é a função dos objetivos de um projeto?','{"A": "Enfeitar a capa", "B": "Indicar o que a pesquisa pretende alcançar", "C": "Substituir a metodologia", "D": "Apresentar somente dificuldades"}'::jsonb,'B','Os objetivos deixam claro o que o projeto pretende realizar.', null),
(5,'PIC Júnior','Por que registrar os procedimentos de uma pesquisa?','{"A": "Para permitir que as etapas sejam compreendidas e avaliadas", "B": "Para esconder erros", "C": "Para evitar a análise dos dados", "D": "Para tornar o projeto mais longo"}'::jsonb,'A','O registro dá transparência ao método e facilita a avaliação e a repetição do estudo.', null),
(6,'PIC Júnior','O que deve ser feito quando os resultados não confirmam a hipótese?','{"A": "Alterar os dados", "B": "Ignorar os resultados", "C": "Analisar os resultados e rever a hipótese, se necessário", "D": "Apagar o projeto"}'::jsonb,'C','Resultados diferentes do esperado também são científicos e devem ser analisados honestamente.', null),
(7,'PIC Júnior','Qual atitude demonstra ética na pesquisa?','{"A": "Inventar dados ausentes", "B": "Citar as fontes utilizadas", "C": "Copiar um texto sem referência", "D": "Omitir resultados inconvenientes"}'::jsonb,'B','Reconhecer fontes e apresentar dados com honestidade são práticas éticas.', null),
(8,'PIC Júnior','Para que serve a metodologia?','{"A": "Explicar como a pesquisa foi realizada", "B": "Mostrar apenas o título", "C": "Substituir a conclusão", "D": "Listar somente os participantes"}'::jsonb,'A','A metodologia descreve os métodos, materiais e procedimentos utilizados.', null),
(9,'PIC Júnior','Qual é uma boa prática ao coletar dados?','{"A": "Modificar registros para combinar com a hipótese", "B": "Anotar as condições e os procedimentos utilizados", "C": "Guardar apenas os resultados favoráveis", "D": "Não identificar as unidades"}'::jsonb,'B','Registros completos ajudam a interpretar e conferir os dados.', null),
(10,'PIC Júnior','O que é uma variável em uma investigação?','{"A": "Um fator ou característica que pode assumir diferentes valores", "B": "Uma resposta sempre fixa", "C": "O nome do pesquisador", "D": "Uma referência bibliográfica"}'::jsonb,'A','Variáveis são características observadas, medidas ou controladas em uma pesquisa.', null),
(11,'PIC Júnior','Por que é importante repetir medições quando isso é adequado?','{"A": "Para escolher o resultado mais bonito", "B": "Para avaliar a variação e a consistência das medidas", "C": "Para aumentar os números artificialmente", "D": "Para dispensar instrumentos"}'::jsonb,'B','Repetições ajudam a perceber variações e avaliar a confiabilidade das medições.', null),
(12,'PIC Júnior','Qual é a finalidade de um gráfico científico?','{"A": "Substituir todos os dados originais", "B": "Facilitar a visualização de padrões e comparações", "C": "Garantir que uma hipótese seja verdadeira", "D": "Esconder valores discrepantes"}'::jsonb,'B','Gráficos organizam visualmente os dados, mas devem ser interpretados com cuidado.', null),
(13,'PIC Júnior','O que deve acompanhar um eixo de gráfico?','{"A": "Uma identificação e, quando aplicável, a unidade", "B": "Somente uma cor", "C": "Uma frase de opinião", "D": "O nome de todos os participantes"}'::jsonb,'A','Rótulos e unidades permitem compreender o que está sendo representado.', null),
(14,'PIC Júnior','O que significa uma conclusão baseada em evidências?','{"A": "Uma afirmação apoiada nos dados e limites do estudo", "B": "Uma opinião escolhida antes da pesquisa", "C": "Uma promessa de resultado futuro", "D": "Uma afirmação sem relação com os objetivos"}'::jsonb,'A','A conclusão deve corresponder ao que os dados permitem afirmar.', null),
(15,'PIC Júnior','Qual é a função da revisão bibliográfica?','{"A": "Conhecer o que já foi publicado sobre o tema", "B": "Evitar a formulação de objetivos", "C": "Substituir a coleta de dados em qualquer pesquisa", "D": "Garantir que não existam limitações"}'::jsonb,'A','A revisão situa o estudo no conhecimento já produzido.', null),
(16,'PIC Júnior','Por que uma pesquisa deve apresentar suas limitações?','{"A": "Para invalidar automaticamente o estudo", "B": "Para deixar claro o alcance dos resultados", "C": "Para esconder problemas", "D": "Para evitar novas pesquisas"}'::jsonb,'B','Limitações ajudam o leitor a entender até onde as conclusões podem ser generalizadas.', null),
(17,'PIC Júnior','Qual é uma forma adequada de apresentar uma tabela?','{"A": "Com título, cabeçalhos claros e unidades quando necessárias", "B": "Sem identificar as colunas", "C": "Com valores aleatórios", "D": "Sem explicar abreviações"}'::jsonb,'A','Tabelas precisam ser legíveis e ter informações suficientes para interpretação.', null),
(18,'PIC Júnior','O que é divulgação científica?','{"A": "Comunicar conhecimentos científicos de forma compreensível e responsável", "B": "Publicar somente opiniões", "C": "Esconder os métodos", "D": "Apresentar resultados sem contexto"}'::jsonb,'A','A divulgação aproxima a ciência da sociedade usando linguagem adequada ao público.', null),
(19,'PIC Júnior','Qual atitude ajuda a evitar plágio?','{"A": "Copiar parágrafos e trocar algumas palavras", "B": "Indicar corretamente as fontes e produzir texto próprio", "C": "Retirar o nome do autor", "D": "Usar imagens sem verificar a licença"}'::jsonb,'B','Citar fontes e distinguir ideias próprias das de terceiros evita apropriação indevida.', null),
(20,'PIC Júnior','O que é um dado qualitativo?','{"A": "Uma descrição ou categoria não expressa primariamente como medida numérica", "B": "Sempre uma temperatura", "C": "Um número decimal", "D": "Uma porcentagem obrigatoriamente"}'::jsonb,'A','Dados qualitativos descrevem características, categorias ou observações.', null),
(21,'PIC Júnior','O que é um dado quantitativo?','{"A": "Uma informação expressa numericamente", "B": "Uma opinião sem medida", "C": "Uma cor sem classificação", "D": "Um relato exclusivamente textual"}'::jsonb,'A','Dados quantitativos podem ser contados ou medidos e expressos em números.', null),
(22,'PIC Júnior','Por que é importante definir critérios antes de analisar dados?','{"A": "Para reduzir decisões arbitrárias durante a análise", "B": "Para garantir qualquer resultado", "C": "Para escolher apenas os dados convenientes", "D": "Para dispensar registros"}'::jsonb,'A','Critérios definidos previamente tornam a análise mais consistente e transparente.', null),
(23,'PIC Júnior','Qual é a melhor atitude ao encontrar um erro em um registro?','{"A": "Corrigir sem deixar rastros", "B": "Apagar todo o conjunto de dados", "C": "Documentar a correção e preservar a informação original quando possível", "D": "Fingir que não aconteceu"}'::jsonb,'C','A rastreabilidade permite compreender o que foi alterado e por quê.', null),
(24,'PIC Júnior','O que torna uma fonte de informação mais confiável?','{"A": "Autoria identificada, evidências e possibilidade de verificação", "B": "Muitos compartilhamentos", "C": "Um título chamativo", "D": "Ausência de referências"}'::jsonb,'A','A confiabilidade depende da qualidade, autoria e verificabilidade da informação.', null),
(25,'PIC Júnior','Qual é o papel da apresentação oral de um projeto?','{"A": "Comunicar objetivo, método, resultados e conclusões", "B": "Ler todos os dados sem explicação", "C": "Evitar perguntas", "D": "Substituir o trabalho realizado"}'::jsonb,'A','Uma apresentação científica sintetiza o estudo e permite dialogar sobre ele.', null),
(26,'REDGIM','No projeto REDGIM, qual é o objetivo geral da análise de imagens de cédulas?','{"A": "Investigar características visuais por métodos computacionais", "B": "Alterar o valor impresso das cédulas", "C": "Produzir novas cédulas", "D": "Substituir o Banco Central"}'::jsonb,'A','A análise de imagens permite estudar padrões visuais e organizar informações para pesquisa.', null),
(27,'REDGIM','O que significa ROI em análise de imagens?','{"A": "Região de interesse", "B": "Registro oficial de identificação", "C": "Relação óptica interna", "D": "Resultado observado individual"}'::jsonb,'A','ROI é a sigla de Region of Interest, ou região de interesse.', null),
(28,'REDGIM','Por que selecionar uma ROI em uma imagem de cédula?','{"A": "Para analisar uma região específica de forma delimitada", "B": "Para apagar a imagem inteira", "C": "Para mudar a denominação da cédula", "D": "Para dispensar a iluminação"}'::jsonb,'A','A ROI delimita a área que será estudada e comparada.', null),
(29,'REDGIM','O que os canais R, G e B representam em uma imagem digital?','{"A": "Vermelho, verde e azul", "B": "Rugosidade, geometria e brilho", "C": "Resolução, grade e borda", "D": "Reflexo, ganho e balanço"}'::jsonb,'A','RGB é um modelo de cores baseado nos canais vermelho, verde e azul.', null),
(30,'REDGIM','O que é um pixel?','{"A": "A menor unidade endereçável de uma imagem raster", "B": "Um tipo de lente", "C": "Uma região sempre circular", "D": "Um arquivo de áudio"}'::jsonb,'A','Uma imagem digital raster é formada por pixels.', null),
(31,'REDGIM','Por que manter a iluminação controlada durante a captura?','{"A": "Para reduzir variações causadas pelas condições de luz", "B": "Para garantir que todas as imagens fiquem iguais em qualquer situação", "C": "Para alterar as cores reais", "D": "Para dispensar a câmera"}'::jsonb,'A','A iluminação influencia os valores de cor e brilho registrados pela câmera.', null),
(32,'REDGIM','O que pode acontecer se a câmera mudar de posição entre capturas?','{"A": "A região analisada pode ficar desalinhada", "B": "A resolução sempre dobra", "C": "Os pixels deixam de existir", "D": "A imagem vira um vetor automaticamente"}'::jsonb,'A','Mudanças de posição podem dificultar a comparação entre regiões correspondentes.', null),
(33,'REDGIM','Qual é a utilidade de registrar a distância e a posição da câmera?','{"A": "Ajudar a padronizar as condições de aquisição", "B": "Aumentar artificialmente a quantidade de dados", "C": "Substituir a identificação das imagens", "D": "Eliminar a necessidade de foco"}'::jsonb,'A','Registrar condições de captura melhora a reprodutibilidade do procedimento.', null),
(34,'REDGIM','O que é um histograma de imagem?','{"A": "Uma representação da distribuição de intensidades dos pixels", "B": "Um mapa de localização geográfica", "C": "Uma lista de nomes de arquivos", "D": "Uma fotografia em três dimensões"}'::jsonb,'A','O histograma mostra quantos pixels apresentam determinados níveis de intensidade.', null),
(35,'REDGIM','Para que serve a análise de componentes principais (PCA)?','{"A": "Resumir a variabilidade dos dados em componentes", "B": "Aumentar a resolução de uma fotografia", "C": "Corrigir automaticamente qualquer erro", "D": "Identificar sempre a origem de uma cédula"}'::jsonb,'A','A PCA transforma variáveis correlacionadas em componentes que explicam parcelas da variabilidade.', null),
(36,'REDGIM','O que representa a variância explicada por um componente principal?','{"A": "A parcela da variabilidade dos dados representada por esse componente", "B": "A porcentagem de cédulas verdadeiras", "C": "O número de pixels da imagem", "D": "A quantidade de fotografias capturadas"}'::jsonb,'A','A variância explicada indica quanto da variação total é representada pelo componente.', null),
(37,'REDGIM','Em um gráfico de scores da PCA, o que cada ponto costuma representar?','{"A": "Uma observação ou amostra projetada nos componentes", "B": "O nome de uma cor", "C": "A unidade de medida da lente", "D": "Uma resposta correta do quiz"}'::jsonb,'A','Os scores mostram a posição das observações no espaço dos componentes principais.', null),
(38,'REDGIM','O que pontos próximos em um gráfico de scores podem indicar?','{"A": "Observações com perfis semelhantes nas variáveis analisadas", "B": "Que são necessariamente a mesma imagem", "C": "Que uma observação está errada", "D": "Que os dados não têm variabilidade"}'::jsonb,'A','Proximidade sugere semelhança no espaço representado, considerando as variáveis e o pré-processamento.', null),
(39,'REDGIM','O que os loadings ajudam a interpretar na PCA?','{"A": "A contribuição ou associação das variáveis com os componentes", "B": "A posição física da câmera", "C": "A data de fabricação da cédula", "D": "O tamanho do arquivo em bytes"}'::jsonb,'A','Os loadings ajudam a entender quais variáveis estão associadas aos componentes.', null),
(40,'REDGIM','Se grupos no gráfico correspondem a regiões diferentes de uma mesma cédula, o que se deve evitar?','{"A": "Concluir que os grupos representam cédulas verdadeiras e falsas sem evidência", "B": "Descrever a distribuição dos pontos", "C": "Verificar quais regiões foram selecionadas", "D": "Analisar os loadings"}'::jsonb,'A','A interpretação deve respeitar como as amostras e os grupos foram definidos.', null),
(41,'REDGIM','Por que identificar corretamente cada região analisada é importante?','{"A": "Para relacionar os resultados à localização correspondente na cédula", "B": "Para mudar o resultado da PCA", "C": "Para evitar a documentação", "D": "Para substituir as imagens originais"}'::jsonb,'A','Sem identificação, pode-se atribuir significado incorreto aos agrupamentos.', null),
(42,'REDGIM','O que é uma matriz de dados em uma análise de imagens?','{"A": "Uma organização de observações e variáveis em linhas e colunas", "B": "Uma moldura para fotografias", "C": "Um tipo de iluminação", "D": "Uma lista de conclusões"}'::jsonb,'A','A matriz reúne valores extraídos das imagens para análises estatísticas.', null),
(43,'REDGIM','Por que padronizar as condições de captura de imagens?','{"A": "Para tornar as comparações mais justas e reduzir fatores externos", "B": "Para garantir que a PCA forme grupos separados", "C": "Para eliminar a necessidade de análise", "D": "Para alterar o conteúdo da cédula"}'::jsonb,'A','Padronização reduz diferenças que poderiam ser causadas pelo processo de captura.', null),
(44,'REDGIM','O que é resolução espacial de uma imagem?','{"A": "A quantidade de detalhes espaciais que pode ser representada", "B": "A quantidade de cores escolhidas pelo pesquisador", "C": "O tempo de exposição", "D": "A temperatura do ambiente"}'::jsonb,'A','A resolução espacial está relacionada à capacidade de representar detalhes na imagem.', null),
(45,'REDGIM','Qual pode ser o efeito de uma sombra sobre a imagem capturada?','{"A": "Alterar os valores de brilho e cor em parte da imagem", "B": "Aumentar sempre a nitidez", "C": "Remover todos os ruídos", "D": "Não produzir nenhum efeito"}'::jsonb,'A','Sombras mudam a iluminação recebida e podem afetar as medidas dos pixels.', null),
(46,'REDGIM','Por que conservar as imagens originais?','{"A": "Para permitir conferência e reprocessamento dos dados", "B": "Para impedir novas análises", "C": "Para reduzir a transparência do estudo", "D": "Para substituir o relatório"}'::jsonb,'A','As imagens originais preservam o registro da aquisição e permitem repetir análises.', null),
(47,'REDGIM','O que é pré-processamento de imagem?','{"A": "Etapas aplicadas antes da análise principal para preparar os dados", "B": "A conclusão final da pesquisa", "C": "A impressão da cédula", "D": "A apresentação oral do projeto"}'::jsonb,'A','Pode incluir operações como recorte, alinhamento ou ajustes definidos no método.', null),
(48,'REDGIM','Se duas imagens apresentam diferenças de iluminação, qual é uma atitude adequada?','{"A": "Investigar e registrar essa diferença antes de comparar os resultados", "B": "Ignorar a diferença", "C": "Afirmar que a cédula mudou", "D": "Apagar a imagem com menor brilho"}'::jsonb,'A','A iluminação é uma condição experimental relevante e precisa ser considerada.', null),
(49,'REDGIM','O que um agrupamento visual na PCA permite afirmar sozinho?','{"A": "Que há observações próximas no espaço dos componentes, sem provar sua causa", "B": "Que existe falsificação comprovada", "C": "Que as amostras têm a mesma origem", "D": "Que o método é infalível"}'::jsonb,'A','Um agrupamento é um padrão exploratório e precisa de contexto e validação.', null),
(50,'REDGIM','Por que a PCA não deve ser tratada como prova isolada de falsificação?','{"A": "Porque é uma ferramenta exploratória e depende dos dados e da validação", "B": "Porque não pode analisar dados numéricos", "C": "Porque funciona apenas com textos", "D": "Porque não produz gráficos"}'::jsonb,'A','A PCA revela padrões, mas não substitui validação independente nem análise pericial.', null)
